'use strict';

// MODULES //

var bench = require( '@stdlib/bench' );
var uniform = require( '@stdlib/random/uniform' );
var zeros = require( '@stdlib/ndarray/zeros' );
var isnan = require( '@stdlib/math/base/assert/is-nan' );
var pow = require( '@stdlib/math/base/special/pow' );
var scalar2ndarray = require( '@stdlib/ndarray/from-scalar' );
var resolveTriangle = require( '@stdlib/blas/base/matrix-triangle-resolve-enum' );
var resolveTranspose = require( '@stdlib/blas/base/transpose-operation-resolve-enum' );
var resolveDiagonal = require( '@stdlib/blas/base/diagonal-type-resolve-enum' );
var format = require( '@stdlib/string/format' );
var pkg = require( './../package.json' ).name;
var dtrsv = require( './../lib' );


// VARIABLES //

var options = {
	'dtype': 'float64'
};
var eopts = {
	'dtype': 'int32'
};


// FUNCTIONS //

/**
* Creates a benchmark function.
*
* @private
* @param {PositiveInteger} len - array length
* @returns {Function} benchmark function
*/
function createBenchmark( len ) {
	var trans;
	var diag;
	var uplo;
	var x;
	var A;

	x = zeros( [ len ], options );
	A = uniform( [ len, len ], -100.0, 100.0, options );

	uplo = scalar2ndarray( resolveTriangle( 'upper' ), eopts );
	trans = scalar2ndarray( resolveTranspose( 'no-transpose' ), eopts );
	diag = scalar2ndarray( resolveDiagonal( 'non-unit' ), eopts );

	return benchmark;

	/**
	* Benchmark function.
	*
	* @private
	* @param {Benchmark} b - benchmark instance
	*/
	function benchmark( b ) {
		var z;
		var i;

		b.tic();
		for ( i = 0; i < b.iterations; i++ ) {
			z = dtrsv( [ x, A, uplo, trans, diag ] );
			if ( typeof z !== 'object' ) {
				b.fail( 'should return an ndarray' );
			}
		}
		b.toc();
		if ( isnan( z.get( i%len ) ) ) {
			b.fail( 'should not return NaN' );
		}
		b.pass( 'benchmark finished' );
		b.end();
	}
}


// MAIN //

/**
* Main execution sequence.
*
* @private
*/
function main() {
	var len;
	var min;
	var max;
	var f;
	var i;

	min = 1; // 10^min
	max = 3; // 10^max

	for ( i = min; i <= max; i++ ) {
		len = pow( 10, i );
		f = createBenchmark( len );
		bench( format( '%s:len=%d', pkg, len ), f );
	}
}

main();
